import java.io.*
import java.util.*

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val output = PrintWriter(System.out)
    val errorOutput = PrintWriter(System.err, true)

    val lines = mutableListOf<String>()
    while (true) {
        val line = reader.readLine()
        if (line == null) break
        lines.add(line)
    }

    errorOutput.println("\n↑入力 ↓出力")

    val one = lines[0].split(" ").map { it.toInt() }
    val L = one[0]
    val R = one[1]
    val C = one[2]

    if (Math.abs(L - R) >= C) {
        val result = (Math.min(Math.max(L, R), Math.min(L, R) + C)) * 2
        output.println(result)
    } else {
        val diff = Math.abs(L - R)
        val newL: Int
        val newR: Int
        if (L > R) {
            newL = L
            newR = R + diff
        } else {
            newL = L + diff
            newR = R
        }
        val remainingC = C - diff
        val result = (remainingC / 2 + newL) * 2
        output.println(result)
    }

    output.flush()
    errorOutput.flush()
}
